CREATE TABLE delivery_claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,claim_number text NOT NULL,shipment_id uuid NOT NULL REFERENCES shipments(id),claim_type text NOT NULL CHECK(claim_type IN('lost','damaged','short','delayed','other')),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','pending_approval','approved','rejected_internal','submitted','investigating','partially_approved','approved_by_carrier','rejected_by_carrier','withdrawn','settled','closed')),description text NOT NULL,claimed_amount numeric(18,2) NOT NULL CHECK(claimed_amount>=0),approved_amount numeric(18,2),settlement_type text CHECK(settlement_type IN('credit_note','cash','replacement')),settlement_reference text,carrier_case_reference text,incident_at timestamptz,evidence_due_at timestamptz,submitted_at timestamptz,resolved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES users(id),approved_at timestamptz,approved_by uuid REFERENCES users(id),UNIQUE(company_id,claim_number),UNIQUE(company_id,id));
CREATE TABLE delivery_claim_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,claim_id uuid NOT NULL REFERENCES delivery_claims(id) ON DELETE CASCADE,item_id uuid NOT NULL REFERENCES items(id),quantity numeric(18,6) NOT NULL CHECK(quantity>0),uom text NOT NULL,unit_value numeric(18,2) NOT NULL CHECK(unit_value>=0),condition_code text CHECK(condition_code IN('lost','damaged','short','unusable','repairable','other')),notes text,UNIQUE(claim_id,item_id,condition_code),FOREIGN KEY(company_id,claim_id) REFERENCES delivery_claims(company_id,id));
CREATE TABLE delivery_claim_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,claim_id uuid NOT NULL REFERENCES delivery_claims(id) ON DELETE CASCADE,evidence_type text NOT NULL CHECK(evidence_type IN('photo','delivery_proof','packing_list','invoice','inspection','carrier_correspondence','other')),reference text NOT NULL,description text,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES users(id),FOREIGN KEY(company_id,claim_id) REFERENCES delivery_claims(company_id,id));
CREATE TABLE delivery_claim_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,claim_id uuid NOT NULL REFERENCES delivery_claims(id) ON DELETE CASCADE,event_type text NOT NULL,from_status text,to_status text,note text,amount numeric(18,2),reference text,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES users(id),FOREIGN KEY(company_id,claim_id) REFERENCES delivery_claims(company_id,id));
ALTER TABLE companies ADD COLUMN delivery_claim_sla_days integer NOT NULL DEFAULT 7 CHECK(delivery_claim_sla_days BETWEEN 1 AND 365);
CREATE VIEW delivery_claim_kpis WITH(security_invoker=true) AS SELECT c.company_id,o.warehouse_id,o.store_id,sh.carrier_service_id,date_trunc('month',c.created_at)::date activity_month,count(*) claims,count(*)FILTER(WHERE c.status NOT IN('settled','closed','rejected_internal','rejected_by_carrier','withdrawn')) open_claims,count(*)FILTER(WHERE c.evidence_due_at<now() AND c.status NOT IN('settled','closed','rejected_internal','rejected_by_carrier','withdrawn')) overdue_claims,sum(c.claimed_amount) claimed_amount,sum(coalesce(c.approved_amount,0)) approved_amount,avg(extract(epoch FROM(c.resolved_at-c.created_at))/86400)FILTER(WHERE c.resolved_at IS NOT NULL) avg_resolution_days FROM delivery_claims c JOIN shipments sh ON sh.id=c.shipment_id JOIN sales_orders o ON o.id=sh.order_id GROUP BY c.company_id,o.warehouse_id,o.store_id,sh.carrier_service_id,date_trunc('month',c.created_at)::date;
ALTER TABLE delivery_claims ENABLE ROW LEVEL SECURITY;ALTER TABLE delivery_claims FORCE ROW LEVEL SECURITY;ALTER TABLE delivery_claim_lines ENABLE ROW LEVEL SECURITY;ALTER TABLE delivery_claim_lines FORCE ROW LEVEL SECURITY;ALTER TABLE delivery_claim_evidence ENABLE ROW LEVEL SECURITY;ALTER TABLE delivery_claim_evidence FORCE ROW LEVEL SECURITY;ALTER TABLE delivery_claim_events ENABLE ROW LEVEL SECURITY;ALTER TABLE delivery_claim_events FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_delivery_claims ON delivery_claims USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_delivery_claim_lines ON delivery_claim_lines USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_delivery_claim_evidence ON delivery_claim_evidence USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_delivery_claim_events ON delivery_claim_events USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON delivery_claims,delivery_claim_lines,delivery_claim_evidence,delivery_claim_events TO stockflow_app;GRANT SELECT ON delivery_claim_kpis TO stockflow_app;CREATE INDEX delivery_claims_queue_idx ON delivery_claims(company_id,status,evidence_due_at);CREATE INDEX delivery_claim_events_timeline_idx ON delivery_claim_events(company_id,claim_id,created_at);
